   "html": "<section class=\"course-list\" aria-labelledby=\"course-list-title\">\n  <header class=\"course-list__header\">\n    <h2 id=\"course-list-title\">继续学习</h2>\n    <p class=\"course-list__stats\">\n      已有 <strong class=\"countup\" data-target=\"12840\">12840</strong> 位同学在学\n    </p>\n  </header>\n\n  <ul class=\"course-grid\" role=\"list\">\n    <li class=\"course-card\" style=\"--i: 0\">\n      <a class=\"course-card__link\" href=\"#\">\n        <div class=\"course-card__cover\" aria-hidden=\"true\"></div>\n        <h3 class=\"course-card__title\">初中代数：一元一次方程</h3>\n        <p class=\"course-card__meta\">12 课时</p>\n        <div class=\"progress\" role=\"progressbar\" aria-label=\"学习进度\"\n             aria-valuemin=\"0\" aria-valuemax=\"100\" aria-valuenow=\"60\" data-value=\"60\">\n          <div class=\"progress__bar\"></div>\n        </div>\n      </a>\n      <button class=\"bookmark\" type=\"button\" aria-pressed=\"false\" aria-label=\"收藏课程\">\n        <svg viewBox=\"0 0 24 24\" width=\"20\" height=\"20\" aria-hidden=\"true\">\n          <path d=\"M6 3h12v18l-6-4-6 4z\" />\n        </svg>\n      </button>\n    </li>\n    <!-- 更多卡片，--i 依次递增 -->\n  </ul>\n</section>",
   "css": ".course-list { padding: var(--space-12) var(--space-6); }\n.course-list__header { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: var(--space-6); }\n.course-list__stats { color: var(--color-muted); }\n.course-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: var(--space-6); list-style: none; padding: 0; margin: 0; }\n.course-card { position: relative; background: var(--color-surface); border: 1px solid var(--color-border); border-radius: var(--radius-md); overflow: hidden; }\n.course-card__link { display: block; padding: var(--space-4); color: inherit; text-decoration: none; }\n.course-card__cover { aspect-ratio: 16 / 9; border-radius: var(--radius-sm); background: linear-gradient(135deg, var(--color-primary-soft), #e0e7ff); margin-bottom: var(--space-3); }\n.course-card__title { font-size: 1rem; margin: 0 0 var(--space-1); }\n.course-card__meta { color: var(--color-muted); font-size: 0.875rem; margin: 0 0 var(--space-3); }\n.course-card .bookmark { position: absolute; top: var(--space-6); right: var(--space-6); }",
