  "video-player": {
   "built": true,
   "name": {
    "zh": "视频观看",
    "en": "Video lesson"
   },
   "summary": {
    "zh": "讲解视频 + 章节列表，完成的章节打勾",
    "en": "Custom play button, lesson progress and a chapter list"
   },
   "structure": {
    "zh": "视频区（自定义播放按钮）→ 本课进度 → 章节列表（每章：序号、标题、时长、完成勾）",
    "en": "Video stage (with play button) → lesson title + progress → chapter list (done chapters show a check)"
   },
   "motions": [
    "play-pause-morph",
    "card-hover-lift",
    "progress-grow",
    "checkmark-draw",
    "ambient-glow",
    "scroll-fade-in",
    "audio-bars",
    "like-count",
    "waveform-progress"
   ],
   "html": "<section class=\"lesson\" aria-labelledby=\"lesson-title\">\n  <div class=\"lesson__stage\">\n    <!-- ambient-glow 的装饰层放这里 -->\n    <div class=\"lesson__video\">\n      <video id=\"lesson-video\" src=\"your-video.mp4\" preload=\"metadata\"></video>\n      <button class=\"play-btn\" type=\"button\" data-state=\"paused\" aria-label=\"播放\">\n        <svg class=\"icon-play\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M8 5v14l11-7z\"/></svg>\n        <svg class=\"icon-pause\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M6 5h4v14H6zM14 5h4v14h-4z\"/></svg>\n      </button>\n    </div>\n  </div>\n\n  <div class=\"lesson__body\">\n    <h2 id=\"lesson-title\">第 3 课：移项与合并同类项</h2>\n    <div class=\"progress\" role=\"progressbar\" aria-label=\"本课进度\"\n         aria-valuemin=\"0\" aria-valuemax=\"100\" aria-valuenow=\"40\" data-value=\"40\">\n      <div class=\"progress__bar\"></div>\n    </div>\n\n    <ol class=\"chapters\" role=\"list\">\n      <li class=\"chapter done\">\n        <span class=\"chapter__title\">什么是移项</span>\n        <span class=\"chapter__time\">03:20</span>\n        <svg class=\"check\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12l5 5 9-10\"/></svg>\n        <span class=\"sr-only\">已完成</span>\n      </li>\n      <li class=\"chapter\">\n        <span class=\"chapter__title\">合并同类项</span>\n        <span class=\"chapter__time\">05:45</span>\n        <svg class=\"check\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12l5 5 9-10\"/></svg>\n      </li>\n    </ol>\n  </div>\n</section>",
   "css": ".lesson { display: grid; grid-template-columns: 2fr 1fr; gap: var(--space-6); padding: var(--space-12) var(--space-6); }\n@media (max-width: 800px) { .lesson { grid-template-columns: 1fr; } }\n.lesson__stage { position: relative; border-radius: var(--radius-lg); overflow: hidden; }\n.lesson__video { position: relative; aspect-ratio: 16 / 9; background: #0f172a; border-radius: var(--radius-lg); overflow: hidden; }\n.lesson__video video { width: 100%; height: 100%; object-fit: cover; }\n.lesson__video .play-btn { position: absolute; inset: 0; margin: auto; }\n.chapters { list-style: none; padding: 0; margin: var(--space-4) 0 0; }\n.chapter { display: grid; grid-template-columns: 1fr auto 24px; gap: var(--space-3); align-items: center; padding: var(--space-3) var(--space-4); border-radius: var(--radius-sm); }\n.chapter__time { color: var(--color-muted); font-variant-numeric: tabular-nums; }\n.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }",
   "js": "",
   "mounts": {
    "card-hover-lift": [
     {
      "sel": ".chapter",
      "add": "lift"
     }
    ],
    "scroll-fade-in": [
     {
      "sel": ".lesson__body",
      "add": "reveal"
     }
    ],
    "ambient-glow": [
     {
      "sel": ".lesson__stage",
      "prepend": "<div class=\"glow\" aria-hidden=\"true\"><span class=\"glow__blob glow__blob--a\"></span><span class=\"glow__blob glow__blob--b\"></span></div>"
     }
    ]
   },
   "wiring": {},
   "groups": []
  },
