   "css": ".field { display: grid; gap: var(--space-1); max-width: 320px; }\n.field label { font-size: 0.9rem; font-weight: 600; }\n.field input { padding: var(--space-3) var(--space-4); border: 1.5px solid var(--color-border); border-radius: var(--radius-sm); background: var(--color-surface); font: inherit; color: inherit; outline: none; }\n.field--line { position: relative; }\n.field--line input { border: 0; border-bottom: 1.5px solid var(--color-border); border-radius: 0; padding-left: 0; padding-right: 0; background: transparent; }\n.field--line::after { content: \"\"; position: absolute; left: 0; right: 0; bottom: 0; height: 2px; background: var(--color-primary); transform: scaleX(0); transition: transform var(--duration-base) var(--ease-out); }\n.field--line:focus-within::after { transform: scaleX(1); }",
