   "html": "",
   "css": ".option { position: relative; isolation: isolate; overflow: hidden; }\n.option::before {\n  content: \"\";\n  position: absolute; inset: 0;\n  z-index: -1;\n  background: var(--color-primary-soft);\n  transform: scaleX(0);\n  transform-origin: left center;\n  transition: transform var(--duration-base) var(--ease-out);\n}\n.option:has(input:checked) { background: var(--color-surface); } /* 背景交给 ::before */\n.option:has(input:checked)::before { transform: scaleX(1); }\n.option.is-correct::before,\n.option.is-wrong::before { opacity: 0; } /* 判题后显示对错颜色 */",
