   "html": "",
   "css": ".option {\n  position: relative;\n  transition:\n    border-color var(--duration-fast),\n    background-color var(--duration-fast);\n}\n.option:hover { border-color: #c7d2fe; }\n.option:has(input:checked) {\n  border-color: var(--color-primary);\n  background: var(--color-primary-soft);\n}\n.option:has(input:checked)::after {\n  content: \"\";\n  position: absolute; inset: -2px;\n  border-radius: inherit;\n  pointer-events: none;\n  animation: option-pulse 400ms var(--ease-out);\n}\n.option:has(input:focus-visible) {\n  outline: 3px solid var(--color-primary);\n  outline-offset: 2px;\n}\n@keyframes option-pulse {\n  from { box-shadow: 0 0 0 0 rgb(79 70 229 / 0.35); }\n  to   { box-shadow: 0 0 0 10px rgb(79 70 229 / 0); }\n}",
