   "html": "<div class=\"toasts\" aria-live=\"polite\"></div>\n<button type=\"button\" data-toast=\"side\">保存</button>",
   "css": ".toasts { position: fixed; left: 50%; bottom: var(--space-6); translate: -50% 0; z-index: 1000; display: grid; gap: var(--space-2); justify-items: center; }\n.toast { padding: var(--space-3) var(--space-4); border-radius: var(--radius-md); background: var(--color-text); color: #fff; font-weight: 600; box-shadow: var(--shadow-md); }\n.toasts:has(.toast--side) { left: auto; right: var(--space-6); translate: none; justify-items: end; }\n.toast--side { animation: toast-side 300ms var(--ease-out); }\n.toast--side.is-leaving { animation: toast-side-out 200ms ease-in forwards; }\n@keyframes toast-side { from { opacity: 0; transform: translateX(110%); } }\n@keyframes toast-side-out { to { opacity: 0; transform: translateX(110%); } }",
   "js": "function showToast(text, variant) {\n  const box = document.querySelector(\".toasts\");\n  const t = document.createElement(\"div\");\n  t.className = \"toast toast--\" + variant;\n  t.textContent = text;\n  box.appendChild(t);\n  setTimeout(() => {\n    if (matchMedia(\"(prefers-reduced-motion: reduce)\").matches) return t.remove();\n    t.classList.add(\"is-leaving\");\n    t.addEventListener(\"animationend\", () => t.remove(), { once: true });\n  }, 4000);\n}\ndocument.querySelectorAll('[data-toast=\"side\"]').forEach((b) => b.addEventListener(\"click\", () => showToast(\"已保存\", \"side\")));",
